#!/usr/bin/env node
/**
 * build-family-art.mjs: writes the Family Math Studio art kit under assets/design/family/art/.
 *
 *   node tools/build-family-art.mjs          # write every generated file
 *   node tools/build-family-art.mjs --check  # fail if any generated file on disk differs from a fresh build
 *
 * Drawing code lives in tools/lib/family-art-{kit,scenes,spots,brand}.mjs, hook cards and math models are the
 * pure modules in assets/design/family/art/. Output is deterministic (same inputs, same bytes). Hand-authored
 * files (icons.svg, math-*.mjs, hook-cards.mjs, LICENSE-NOTES.md) are never touched here.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import {
  HOOK_KINDS,
  renderHookCard,
  sampleSlots,
} from "../assets/design/family/art/hook-cards.mjs";
import { fromHsl, mix, parseColor, toHex, toHsl } from "./lib/color-math.mjs";
import { markBody, markSvg, ogCard, wordmarkSvg } from "./lib/family-art-brand.mjs";
import { svg } from "./lib/family-art-kit.mjs";
import { renderScene } from "./lib/family-art-scenes.mjs";
import { renderSpot, SPOT_IDS, SPOTS } from "./lib/family-art-spots.mjs";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const ART = join(ROOT, "assets/design/family/art");
const check = process.argv.includes("--check");

// Ten unit identities. Decorative hues, none in the violet/magenta band; the unit NUMBER is always printed beside them.
const ACCENTS = [
  "#1FA6A2",
  "#3F7CB8",
  "#D9694A",
  "#E0902F",
  "#8A9A3B",
  "#D9694A",
  "#3E9B6B",
  "#9C6B3C",
  "#2A93B5",
  "#F2C15B",
];
const WHITE = parseColor("#FFFFFF");
const tint = (hex, base, t) => toHex(mix(parseColor(hex), base, t)).toUpperCase();
/** Dark-theme tint: same hue, low saturation, dark (an RGB mix with navy drags warm hues toward violet). */
const darkTint = (hex) => {
  const { h, s } = toHsl(parseColor(hex));
  const c = fromHsl({ h, s: Math.min(0.32, s * 0.45), l: 0.22 });
  return toHex(c).toUpperCase();
};

const toc = JSON.parse(readFileSync(join(ROOT, "data/reveal-toc-2025.json"), "utf8")).units;
const landing = JSON.parse(
  readFileSync(join(ROOT, "data/family-landing-units.json"), "utf8"),
).units;
export const UNITS = ACCENTS.map((accent, i) => ({
  unit: i + 1,
  accent,
  tint: tint(accent, WHITE, 0.82),
  tintDark: darkTint(accent),
  nameEn: toc.find((u) => u.unit === i + 1).title,
  nameEs: landing[String(i + 1)].nameEs,
}));

const pad2 = (n) => String(n).padStart(2, "0");
const files = new Map(); // relative path -> content
const put = (rel, content) => files.set(rel, content);

// ---- scenes, spots, hook card samples
for (const u of UNITS) put(`scenes/unit-${pad2(u.unit)}.svg`, renderScene(u.unit));
for (const id of SPOT_IDS) put(`spots/${id}.svg`, `${renderSpot(id).trim()}\n`);
for (const k of HOOK_KINDS)
  put(`hooks/${k}.svg`, `${renderHookCard(k, sampleSlots(k, "en"), { lang: "en" })}\n`);

// ---- index (the gallery page and tests read this instead of listing files)
put(
  "index.json",
  `${JSON.stringify(
    {
      scenes: UNITS.map((u) => ({
        unit: u.unit,
        file: `scenes/unit-${pad2(u.unit)}.svg`,
        name: u.nameEn,
      })),
      spots: SPOT_IDS.map((id) => ({ id, file: `spots/${id}.svg`, title: SPOTS[id][0] })),
      hooks: HOOK_KINDS,
      og: UNITS.map((u) => ({
        unit: u.unit,
        en: `brand/og/unit-${pad2(u.unit)}.svg`,
        es: `brand/og/unit-${pad2(u.unit)}-es.svg`,
      })),
    },
    null,
    2,
  )}\n`,
);

// ---- units + css
put("units.json", `${JSON.stringify(UNITS, null, 2)}\n`);
const unitCss = UNITS.map(
  (u) => `[data-unit="${u.unit}"]{--unit-accent:${u.accent};--unit-accent-tint:${u.tint}}`,
).join("\n");
const darkVars =
  "--art-card:#223245;--art-ground:#2B3C4F;--art-coral:#E07B5E;--art-blue:#7FA8D4;--art-green:#8FC08E;--art-board:#0F2236;--art-board-panel:#1B3A58";
put(
  "art.css",
  `/* Family Math Studio art kit: the variables the SVG art reads, the ten unit identities and the celebration motion.
   Generated by tools/build-family-art.mjs. The art also reads --ink, --paper and (optionally) --unit-accent /
   --unit-accent-tint from the page theme; every one has a token fallback inside the SVG. */
:root{--art-card:#FFFFFF;--art-ground:#E6E0D0;--art-amber:#F2C15B;--art-coral:#D9694A;--art-blue:#6F9BC9;--art-green:#7FB27E;--art-eye:#2A1D16;--art-board:#17324D;--art-board-text:#F7F4EC;--art-board-panel:#24496D}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){${darkVars}}}
:root[data-theme="dark"]{${darkVars}}
${unitCss}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) [data-unit]{--unit-accent-tint:var(--unit-tint-dark)}}
${UNITS.map((u) => `[data-unit="${u.unit}"]{--unit-tint-dark:${u.tintDark}}`).join("\n")}
:root[data-theme="dark"] [data-unit]{--unit-accent-tint:var(--unit-tint-dark)}
.fa-hero{display:block;inline-size:100%;block-size:auto;aspect-ratio:1200/320;max-block-size:240px;object-fit:cover}
@media (max-width:640px){.fa-hero{aspect-ratio:390/180;max-block-size:none}}

/* Celebration. Static by default: the check is fully drawn, the badge and stars sit still, confetti is a still scatter.
   Motion exists only for people who have not asked for less, runs once, and never flashes. */
.fc-check .fc-tick{stroke-dasharray:1;stroke-dashoffset:0}
@media (prefers-reduced-motion:no-preference){
  .fc-check.is-playing .fc-tick{animation:fc-draw 320ms cubic-bezier(.2,.7,.2,1) both}
  .fc-pop.is-playing{animation:fc-pop 200ms cubic-bezier(.2,.7,.2,1) both;transform-origin:50% 50%;transform-box:fill-box}
  .fc-nudge.is-playing{animation:fc-nudge 320ms ease-in-out both}
  .fc-confetti.is-playing .fc-piece{animation:fc-fall 1100ms cubic-bezier(.2,.7,.2,1) both;animation-delay:calc(var(--i,0) * 60ms)}
  @keyframes fc-draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
  @keyframes fc-pop{0%{transform:scale(.88);opacity:.2}60%{transform:scale(1.06);opacity:1}100%{transform:scale(1)}}
  @keyframes fc-nudge{0%,100%{transform:translateX(0)}40%{transform:translateX(5px)}70%{transform:translateX(-3px)}}
  @keyframes fc-fall{from{transform:translateY(-24px) rotate(0);opacity:0}15%{opacity:1}to{transform:translateY(0) rotate(var(--r,40deg));opacity:1}}
}
`,
);

// ---- celebration sprite
const CONF = [
  '<circle cx="8" cy="8" r="5"/>',
  '<path d="M8 2l6 11H2z"/>',
  '<rect x="3" y="3" width="10" height="10" rx="2"/>',
  '<path d="M8 1v14M1 8h14" class="fc-ln"/>',
  '<path d="M1 11q3.5-8 7 0t7 0" class="fc-ln"/>',
  '<path d="M8 1l6 7-6 7-6-7z"/>',
];
put(
  "celebration.svg",
  `<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false">
<!-- Celebration set. <svg class="fc-pop"><use href="#fc-badge"/></svg>. Motion lives in art.css and only runs under
     prefers-reduced-motion: no-preference; without it every symbol is a still picture. -->
<defs><style>.fc-b{fill:var(--unit-accent,#1FA6A2)}.fc-y{fill:var(--art-amber,#F2C15B)}.fc-k{fill:var(--ink,#17324D)}.fc-w{fill:var(--art-card,#FFFFFF)}.fc-ln{fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}.fc-ck{fill:none;stroke:var(--ink,#17324D);stroke-width:6;stroke-linecap:round;stroke-linejoin:round}</style></defs>
<symbol id="fc-badge" viewBox="0 0 96 96"><path d="M30 60 22 90l26-12 26 12-8-30z" class="fc-y"/><circle cx="48" cy="38" r="30" class="fc-b"/><circle cx="48" cy="38" r="22" class="fc-w"/><path d="M48 21l5.2 10.6 11.7 1.7-8.5 8.2 2 11.6L48 47.600l-10.400 5.500 2-11.600-8.500-8.200 11.700-1.700z" class="fc-y"/></symbol>
<symbol id="fc-star" viewBox="0 0 48 48"><path d="M24 4l6.200 13.400 14.600 1.800-10.800 10 2.800 14.400L24 36.400 11.200 43.600 14 29.200 3.200 19.200l14.600-1.800z" class="fc-y"/></symbol>
<symbol id="fc-star-empty" viewBox="0 0 48 48"><path d="M24 4l6.200 13.400 14.600 1.800-10.800 10 2.800 14.400L24 36.400 11.200 43.600 14 29.200 3.200 19.200l14.600-1.800z" fill="none" stroke="var(--ink,#17324D)" stroke-width="3" stroke-linejoin="round" stroke-dasharray="2 5" stroke-linecap="round"/></symbol>
<symbol id="fc-check" viewBox="0 0 64 64"><circle cx="32" cy="32" r="28" class="fc-b"/><circle cx="32" cy="32" r="28" fill="none" stroke="var(--ink,#17324D)" stroke-width="3"/><path class="fc-ck fc-tick" pathLength="1" d="M19 33l9 9 17-19"/></symbol>
${CONF.map((c, i) => `<symbol id="fc-confetti-${i + 1}" viewBox="0 0 16 16"><g class="${i % 3 === 0 ? "fc-b" : i % 3 === 1 ? "fc-y" : "fc-k"}" color="${i % 3 === 0 ? "var(--unit-accent,#1FA6A2)" : i % 3 === 1 ? "var(--art-amber,#F2C15B)" : "var(--ink,#17324D)"}">${c}</g></symbol>`).join("\n")}
</svg>
`,
);

// ---- brand
put("brand/mark.svg", markSvg());
put("brand/favicon.svg", `${svg({ w: 96, h: 96, body: markBody() })}`);
put("brand/icon-maskable.svg", svg({ w: 96, h: 96, body: markBody({ maskable: true }) }));
put("brand/icon-opaque.svg", svg({ w: 96, h: 96, body: markBody({ square: true }) }));
put("brand/wordmark.svg", wordmarkSvg());
put(
  "brand/manifest.webmanifest",
  `${JSON.stringify(
    {
      name: "Family Math Studio",
      short_name: "Math Studio",
      description: "Math at home, a little at a time. Optional. No grades. English and Spanish.",
      lang: "en",
      display: "standalone",
      theme_color: "#17324D",
      background_color: "#F7F4EC",
      icons: [
        { src: "icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
        { src: "icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
        { src: "icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
      ],
    },
    null,
    2,
  )}\n`,
);
for (const u of UNITS) {
  put(
    `brand/og/unit-${pad2(u.unit)}.svg`,
    ogCard({
      unit: u.unit,
      titleEn: u.nameEn,
      titleEs: u.nameEs,
      accent: u.accent,
      tint: u.tint,
      lang: "en",
    }),
  );
  put(
    `brand/og/unit-${pad2(u.unit)}-es.svg`,
    ogCard({
      unit: u.unit,
      titleEn: u.nameEn,
      titleEs: u.nameEs,
      accent: u.accent,
      tint: u.tint,
      lang: "es",
    }),
  );
}

// ---- README (icon ids are read from the sprite so the list can never drift from it)
const sprite = readFileSync(join(ART, "icons.svg"), "utf8");
const iconIds = [...sprite.matchAll(/<symbol id="(fi-[a-z0-9-]+)"/g)].map((m) => m[1]);
const base = iconIds.filter((id) => !id.endsWith("-fill"));
const fills = iconIds.filter((id) => id.endsWith("-fill"));
put(
  "README.md",
  `# Family Math Studio art kit

Original SVG, drawn for this repo (see \`LICENSE-NOTES.md\`). No raster, no external request, no script. Generated files come from
\`npm run build:family-art\`; \`npm run validate:family-art\` proves every file is well formed, small, accessible and in the palette.

## What is here

| Path | What | Count |
| --- | --- | --- |
| \`icons.svg\` | ONE inline-able sprite, 24px grid, 1.75px round stroke, \`currentColor\` | ${base.length} icons + ${fills.length} filled variants |
| \`scenes/unit-NN.svg\` | Unit hero band, 1200x320, crops to 390x180 (\`preserveAspectRatio="slice"\`), decorative | ${UNITS.length} |
| \`spots/*.svg\` | Spot illustrations, 240x180, \`role="img"\` with a \`<title>\` | ${SPOT_IDS.length} |
| \`hook-cards.mjs\` | Price tag, recipe card, score board, map pin, ticket, receipt as pure SVG functions | ${HOOK_KINDS.length} |
| \`hooks/*.svg\` | Static English samples of the hook cards | ${HOOK_KINDS.length} |
| \`math-models.mjs\` | \`renderModel({kind,data,alt},{lang})\`, ten model kinds (lesson data to SVG) | 10 |
| \`celebration.svg\`, \`art.css\` | badge, stars, check-draw, confetti shapes; motion only under \`prefers-reduced-motion: no-preference\` | 12 symbols |
| \`brand/\` | mark, wordmark, favicon, app icons, manifest, one Open Graph card per unit and language | see \`brand/\` |
| \`units.json\` | Unit accent, tint, dark tint and names (EN from the Reveal TOC, ES from the landing data) | ${UNITS.length} |

## Using the art

Inline the sprite once per page, then \`<svg class="fi" aria-hidden="true"><use href="#fi-check"/></svg>\` (\`.fi{width:1.5rem;height:1.5rem}\`).
Icons are decorative unless they are the only label of a control; give that control an accessible name instead of titling the icon.

Scenes and spots read these CSS custom properties, each with a token fallback inside the file:
\`--ink\`, \`--paper\`, \`--unit-accent\`, \`--unit-accent-tint\` (set by \`[data-unit="N"]\` in \`art.css\`), plus \`--art-card\`, \`--art-ground\`,
\`--art-amber\`, \`--art-coral\`, \`--art-blue\`, \`--art-green\`. Skin and hair tones are fixed on purpose and do not change in dark mode.
Shapes carry meaning; hue is decoration. Everything reads in grayscale.

Inline an SVG to get theming. Loaded through \`<img>\` or CSS \`url()\` it shows the fallback colours (the light theme).

Decorative art is \`aria-hidden="true"\`. Informative art ships \`role="img"\` and a \`<title>\`; if the page already says the same thing in
words, put \`aria-hidden="true"\` on the host instead of removing the title.

## Math models

\`import { renderModel } from "./math-models.mjs"\`; \`renderModel({ kind, data, alt }, { lang: "en" | "es" })\` returns an SVG string (\`""\` for
\`kind: "none"\`). \`alt\` becomes the \`<title>\`; the \`<desc>\` is computed from the numbers passed in, and an unknown value is described as
unknown, never revealed. Data shapes follow \`docs/specs/family-homework-v3.md\`. Beyond that table: \`area.dims\` also takes \`offset\` (parallelogram
top-edge shift) or \`slant\` (side length; the offset is derived), \`split: [a, b]\` on a rectangle (the two parts must add up to \`base\`), and
\`apex\` on a triangle; a \`unit\` of \`$\`, \`dollars\` or \`dólares\` prints as \`$20\`. An unknown kind, a missing field or an unrecognized key throws.
Ids carry the language (\`fm-<hash>-en-...\`), so the EN and ES copies of a model can share a page. Gallery: \`design/family-system/art.html\`.

## Rendering the PNGs

\`npm run build:family-brand-icons\` renders \`brand/icon-192.png\`, \`icon-512.png\`, \`icon-maskable-512.png\`, \`apple-touch-icon.png\`,
\`favicon-32.png\` and \`brand/og/unit-NN[-es].png\` from the SVG sources with the repo's Playwright Chromium (fixed viewport, device scale 1,
no animation). Open Graph text uses the system UI font at render time, so those PNGs are reproducible per machine, not across machines.

## Icon list (ids)

${base.map((id) => `- \`${id}\``).join("\n")}

Filled (active) variants:

${fills.map((id) => `- \`${id}\``).join("\n")}

## Scenes

${UNITS.map((u) => `- \`scenes/unit-${pad2(u.unit)}.svg\`: Unit ${u.unit}, ${u.nameEn}${u.unit === 10 ? " (mindset scene)" : ""}`).join("\n")}

## Spot illustrations

${SPOT_IDS.map((id) => `- \`spots/${id}.svg\``).join("\n")}
`,
);

// ---- write or check
let stale = 0;
for (const [rel, content] of [...files].sort(([a], [b]) => a.localeCompare(b))) {
  const path = join(ART, rel);
  if (check) {
    if (!existsSync(path) || readFileSync(path, "utf8") !== content) {
      console.error(`STALE ${rel}`);
      stale++;
    }
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
  }
}
if (check) {
  if (stale) {
    console.error(
      `${stale} generated file(s) differ from a fresh build; run npm run build:family-art`,
    );
    process.exit(1);
  }
  console.log(`PASS build-family-art --check (${files.size} generated files up to date)`);
} else {
  console.log(`wrote ${files.size} files under assets/design/family/art/`);
}
